var b=$input.first().json.body||{};if(typeof b==='string'){try{b=JSON.parse(b);}catch(e){b={};}}
function S(v,n){return String(v==null?'':v).trim().slice(0,n||200);}
var kind=S(b.kind,10),undo=b.undo===true||b.undo==='true';
var now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
if(kind==='new'){var lab=S(b.label,200);if(!lab)throw new Error('Missing task');var due=S(b.due,10);if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due))due='';return [{json:{kind:kind,label:lab,notes:S(b.notes,1000),due:due,by:S(b.by,80),now:now}}];}
if(kind==='jobtask'){var id=Number(b.id)||0;if(!id)throw new Error('Missing task id');return [{json:{kind:kind,id:id,by:S(b.by,80),now:now,undo:undo}}];}
/* Enquiry checklist: st (Done / Open / In hand) sets that status; without st it ticks Done (undo = Open), as before. */
if(kind==='enq'){var job=S(b.job,20).replace(/^#/,'');if(!job||!S(b.tx))throw new Error('Missing job or task');var st=['Done','Open','In hand'].indexOf(S(b.st,10))>-1?S(b.st,10):'';return [{json:{kind:kind,job:job,tx:S(b.tx,400),by:S(b.by,80),now:now,undo:undo,st:st}}];}
/* Enquiry requirements (Set up tasks on an enquiry): sets enq_json.reqs to the ticked keys. */
if(kind==='enqreqs'){var job2=S(b.job,20).replace(/^#/,'');if(!job2)throw new Error('Missing job');var OK=['survey','estimate','drawings','supq','subq','docs','programme'];var R=(Array.isArray(b.reqs)?b.reqs:[]).map(function(x){return S(x,20);}).filter(function(x,i,a){return OK.indexOf(x)>-1&&a.indexOf(x)===i;});return [{json:{kind:kind,job:job2,reqs:R,by:S(b.by,80),now:now}}];}
/* enqst: the Estimate / Programme status (enq_json.st.estimate / .programme), set from the task drawer's status buttons (Save Act). */
if(kind==='enqst'){var job3=S(b.job,20).replace(/^#/,'');var k3=S(b.k,20),v3=S(b.val,40);var OKV={estimate:['Not started','In progress','Ready for review','Complete'],programme:['Not started','Draft in progress','Draft ready']};if(!job3||!OKV[k3]||OKV[k3].indexOf(v3)<0)throw new Error('Unknown status');return [{json:{kind:kind,job:job3,k:k3,val:v3,by:S(b.by,80),now:now}}];}
/* clearenq: after the Enquiry checklist has been moved into task rows (cbs-tasks-act migrate_enq), empty enq_json.tasks on those jobs (kept as tasks_old). */
if(kind==='clearenq'){var J=(Array.isArray(b.jobs)?b.jobs:[]).map(function(x){return S(x,20).replace(/^#/,'');}).filter(Boolean);if(!J.length)throw new Error('Missing jobs');return [{json:{kind:kind,jobs:J,by:S(b.by,80),now:now}}];}
throw new Error('Unknown task kind');

var p=$('Prep').first().json;var H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
if(p.kind==='new'){var row={job_no:'',req:'custom',kind:'custom',label:p.label,notes:p.notes,due_on:p.due,status:'',created_by:p.by||'Actions board',created_at:p.now};
 var r=await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=jobtasks&k='+K,body:row,json:true,timeout:20000});
 return [{json:{ok:true,kind:'new',row:r}}];}
if(p.kind==='jobtask'){var body=p.undo?{status:'',done_by:'',done_at:''}:{status:'Done',done_by:p.by||'Actions board',done_at:p.now};
 await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=jobtasks&id='+p.id+'&k='+K+'&partial=1',body:body,json:true,timeout:20000});
 return [{json:{ok:true,kind:'jobtask',id:p.id,status:body.status}}];}
function jk(v){return String(v==null?'':v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();}
function latest(job){return $input.all().map(function(i){return i.json;}).filter(function(r){return r&&jk(r.ref)===jk(job);}).sort(function(a,b){return Number(b.id)-Number(a.id);})[0];}
if(p.kind==='clearenq'){var out=[];p.jobs.forEach(function(job){var rw=latest(job);if(!rw)return;var e0={};try{e0=JSON.parse(rw.enq_json||'{}')||{};}catch(x){}
  if(!Array.isArray(e0.tasks)||!e0.tasks.length)return;e0.tasks_old=(Array.isArray(e0.tasks_old)?e0.tasks_old:[]).concat(e0.tasks);e0.tasks=[];e0.updated_at=new Date().toISOString();
  out.push({json:{ok:true,kind:'enq',rid:rw.id,enq_json:JSON.stringify(e0)}});});
 return out.length?out:[{json:{ok:true,kind:'none'}}];}
var row2=latest(p.job);
if(!row2)return [{json:{ok:false,message:'Job not found'}}];
var e={};try{e=JSON.parse(row2.enq_json||'{}')||{};}catch(x){}
if(p.kind==='enqreqs'){e.reqs=p.reqs;e.updated_at=new Date().toISOString();return [{json:{ok:true,kind:'enq',rid:row2.id,enq_json:JSON.stringify(e)}}];}
if(p.kind==='enqst'){e.st=(e.st&&typeof e.st==='object')?e.st:{};e.st[p.k]=p.val;e.updated_at=new Date().toISOString();return [{json:{ok:true,kind:'enq',rid:row2.id,enq_json:JSON.stringify(e)}}];}
var T=Array.isArray(e.tasks)?e.tasks:[];var hit=false;
T.forEach(function(t){if(!hit&&t&&String(t.tx||'').trim()===p.tx){t.st=p.st||(p.undo?'Open':'Done');hit=true;}});
if(!hit)return [{json:{ok:false,message:'Task not found on the job'}}];
e.tasks=T;e.updated_at=new Date().toISOString();
return [{json:{ok:true,kind:'enq',rid:row2.id,enq_json:JSON.stringify(e)}}];

